import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/security.md","filePath":"dynamic-record-view/security.md"}'),r={name:"dynamic-record-view/security.md"};function c(n,e,d,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>Status: <strong>Implemented.</strong> This documents the hardening actually in place, with real code references.</p><h2 id="url-scheme-allowlist-linkviewfield" tabindex="-1">URL scheme allowlist (<code>LinkViewField</code>) <a class="header-anchor" href="#url-scheme-allowlist-linkviewfield" aria-label="Permalink to &quot;URL scheme allowlist (`LinkViewField`)&quot;">​</a></h2><p><code>App\\Support\\DynamicRecordView\\Core\\Fields\\LinkViewField::getUrl()</code> only renders a URL built by <code>linkUsing()</code> if <code>isSafeUrl()</code> accepts it:</p><ul><li>Relative/internal URLs (no scheme, e.g. <code>/customers/1</code>) are always allowed.</li><li>Absolute URLs must use <code>http</code>, <code>https</code>, <code>mailto</code>, or <code>tel</code> (<code>LinkViewField::ALLOWED_SCHEMES</code>). Anything else — <code>javascript:</code>, <code>data:</code>, <code>vbscript:</code>, etc. — is silently dropped (<code>getUrl()</code> returns <code>null</code>, so the field renders no link at all rather than an unsafe one).</li><li>Control characters (<code>\\x00</code>-<code>\\x1f</code>) anywhere in the URL reject it outright.</li></ul><p>See <code>tests/Feature/DynamicRecordView/SecurityHardeningTest.php</code> for the rejected-scheme cases.</p><h2 id="fail-closed-registry" tabindex="-1">Fail-closed registry <a class="header-anchor" href="#fail-closed-registry" aria-label="Permalink to &quot;Fail-closed registry&quot;">​</a></h2><p><code>App\\Support\\DynamicRecordView\\Core\\RecordViewRegistry</code> only resolves a <code>DynamicRecordView</code> for a key that was explicitly <code>register()</code>-ed. An unknown key throws <code>UnknownRecordViewKeyException</code> before anything is instantiated — there is no fallback, wildcard, or convention-based lookup that could resolve a view the developer didn&#39;t register.</p><h2 id="authorized-resolution-only" tabindex="-1">Authorized resolution only <a class="header-anchor" href="#authorized-resolution-only" aria-label="Permalink to &quot;Authorized resolution only&quot;">​</a></h2><p><code>App\\Support\\DynamicRecordView\\Resolution\\RecordResolver::resolve()</code> never calls <code>Model::findOrFail()</code>. It always goes through the view&#39;s own <code>query()</code>, so a record excluded by that query (soft delete, tenant scope, explicit authorization <code>where()</code>) 404s exactly like a record that doesn&#39;t exist — a tampered id can&#39;t distinguish &quot;doesn&#39;t exist&quot; from &quot;exists but you can&#39;t see it&quot;. <code>resolveFresh()</code> drops the per-request memoization cache so a record deleted or de-authorized between an initial render and a later Livewire action is caught on the very next action, not just at mount.</p><h2 id="transactional-re-checked-re-locked-mutation" tabindex="-1">Transactional, re-checked, re-locked mutation <a class="header-anchor" href="#transactional-re-checked-re-locked-mutation" aria-label="Permalink to &quot;Transactional, re-checked, re-locked mutation&quot;">​</a></h2><p><code>App\\Support\\DynamicRecordView\\Resolution\\RelationshipMutator::link()</code> / <code>unlink()</code>:</p><ol><li>Re-resolve the parent + content block fresh through <code>EmbeddedTableContext</code> — the same trusted path reads use — never trusting a client-supplied relation name, model class, or SQL field. Only bounded scalar identifiers (<code>recordViewKey</code>, parent id, section, tab, content key, candidate/related id) ever cross the wire.</li><li>Open a <code>DB::transaction()</code> and re-fetch both parent and candidate/related row with <code>lockForUpdate()</code> — a concurrent request may have changed either row since the pre-transaction resolution.</li><li>Re-check link/unlink authorization (<code>getLinkAuthorization()</code> / <code>getUnlinkAuthorization()</code>) inside the lock.</li><li>Every failure path (<code>safeAbortUnless()</code>) throws a generic <code>HttpException(422, &#39;Unable to complete this action.&#39;)</code> — never a message that distinguishes &quot;doesn&#39;t exist&quot; from &quot;not authorized&quot;, so a client can&#39;t probe for valid ids by comparing error text.</li></ol><h2 id="non-nullable-fk-unlink-is-architecturally-rejected" tabindex="-1">Non-nullable-FK Unlink is architecturally rejected <a class="header-anchor" href="#non-nullable-fk-unlink-is-architecturally-rejected" aria-label="Permalink to &quot;Non-nullable-FK Unlink is architecturally rejected&quot;">​</a></h2><p>For a <code>HasMany</code>/<code>MorphMany</code> relation whose foreign key is <code>NOT NULL</code> (both canonical examples: <code>Application.submodule_id</code>, <code>City.country_id</code>), an ordinary Unlink would require setting that FK to <code>null</code>, which the schema forbids. <code>RelationshipActions::assertSupportedFor()</code> and <code>RelationshipMutator::performUnlink()</code> do not special-case this — Unlink simply isn&#39;t offered; only <code>allowReassignment()</code>-gated Link (re-pointing the FK to a new parent) is available. This is a real schema limitation, not a missing feature — see <a href="./relationship-actions">relationship-actions.md</a> and <a href="./troubleshooting">troubleshooting.md</a>.</p><h2 id="state-normalization" tabindex="-1">State normalization <a class="header-anchor" href="#state-normalization" aria-label="Permalink to &quot;State normalization&quot;">​</a></h2><p><code>RecordSection::normalizeActiveTabKey()</code> rejects any client-supplied active tab candidate that is empty, longer than <code>RecordSection::MAX_TAB_KEY_LENGTH</code> (100 chars), not a defined tab key, or not currently authorized for the resolved record — falling back to the default authorized tab in every case. <code>RecordView</code> and <code>OtherData</code> both self-heal <code>activeTab</code> through this method at render time (not just on the explicit <code>setActiveTab</code> action), so a stale or tampered <code>activeTab</code> property can never render unauthorized tab content.</p><h2 id="what-this-does-not-cover" tabindex="-1">What this does not cover <a class="header-anchor" href="#what-this-does-not-cover" aria-label="Permalink to &quot;What this does not cover&quot;">​</a></h2><ul><li>No CSRF-specific code here — Livewire&#39;s own CSRF protection covers all action calls (<code>link</code>, <code>unlink</code>, <code>setActiveTab</code>, etc.); this engine adds no additional token handling and needs none.</li><li>No rate limiting on the Relation Picker search — out of scope for this engine; apply route/middleware-level throttling if a specific picker needs it.</li></ul>',19)])])}const m=o(r,[["render",c]]);export{p as __pageData,m as default};
